<script setup lang="ts">import type {SpatialLayerMode} from '@/types';defineProps<{mode:SpatialLayerMode;level:string;timeEnabled:boolean}>();defineEmits<{mode:[SpatialLayerMode];back:[];reset:[]}>();const levelName=(level:string)=>({SITE:'园区',BUILDING:'建筑',DEVICE:'设备'}[level]||level);</script>
<template><div class="three-toolbar"><el-radio-group :model-value="mode" size="small" @change="$emit('mode',$event as SpatialLayerMode)"><el-radio-button value="CARBON">碳排</el-radio-button><el-radio-button value="ENERGY">能源</el-radio-button><el-radio-button value="DEVICE">设备</el-radio-button></el-radio-group><span class="three-level">{{levelName(level)}}</span><el-button v-if="level!=='SITE'" size="small" @click="$emit('back')">返回上级</el-button><el-button size="small" @click="$emit('reset')">重置视角</el-button><span v-if="!timeEnabled" class="three-no-time">暂无小时结果</span></div></template>
